    if EntryRecref.FindFirst then begin  
      MyFieldRef := EntryRecref.Field(3);  
      Message(Text000, EntryRecref.RecordId, MyFieldRef.Value);  
      MyFieldRef.Validate('1210');  
      EntryRecref.Modify;  
      Message(Text001, EntryRecref.RecordId, MyFieldRef.Value);  
    end;  
end;
```

